using System.Text.Json;
using Lain.Core;
using Lain.Desktop.Presentation;

var assertions = 0;
var now = DateTimeOffset.Parse("2026-10-30T16:00:00Z");
var account = new AccountDto("account-a", "My custom saved account name", "synthetic", true, "api-key", "unverified");
AccountOutcomeSummaryDto Build(AccountDto? selected = null, RouteDto[]? routes = null, QuotaDto[]? quotas = null, StatusDto? status = null) =>
    AccountOutcomeSummary.Build(selected ?? account, routes ?? [], quotas ?? [], status, now);
AccountOutcomeRow Row(AccountOutcomeSummaryDto summary, string code) => summary.Rows.Single(r => r.Code == code);
var legacy = Build();
Check(legacy.AccountName == account.Name && legacy.AccountId == account.Id, "custom name and account identity preserved");
Check(Row(legacy, "credential").State == "configured", "local account snapshot reported separately");
Check(Row(legacy, "inference").State == "unknown" && Row(legacy, "inference").Evidence == "legacy_unknown", "legacy API key does not invent inference capability");
Check(Row(legacy, "monitoring").State == "not_observed", "absence is no monitoring observation");
Check(Row(legacy, "gateway").State == "unknown", "missing service snapshot remains unknown");
Check(legacy.Rows.Count == 5, "small bounded row set without extra first-look cards");
var configured = account with { Capabilities = [new("inference", "available"), new("quota", "unverified"), new("models", "unverified")] };
var freshQuota = new QuotaDto(account.Id, null, "synthetic-provider", "ok", now, now, null, "requests", 0, 100, 100, false,
    FreshUntil: now.AddMinutes(5));
var ready = new StatusDto(1, "0.8.0", "ready", true, 5, 5, now);
var enabled = Build(configured, [Route("r1"), Route("r2", false), Route("r3", visible: false)], [freshQuota], ready);
Check(enabled.ConfiguredRouteCount == 3 && enabled.EnabledVisibleRouteCount == 1, "configured versus enabled visible route counts");
Check(Row(enabled, "inference").State == "configured" && Row(enabled, "inference").Value.Contains("unverified"), "available capability never claims successful inference");
Check(Row(enabled, "monitoring").State == "fresh", "actual zero-usage monitoring reading retained");
Check(Row(enabled, "gateway").State == "reported_ready", "global gateway state is explicitly reported");
Check(Row(enabled, "gateway").Detail.Contains("does not establish"), "global readiness is not account qualification");
Check(Row(enabled, "model_discovery").State == "configured" && Row(enabled, "model_discovery").Value.Contains("unverified"), "discovery declaration not discovery success");
var stale = freshQuota with { State = "stale", LastSuccessAt = now.AddHours(-2), FreshUntil = now.AddHours(-1) };
Check(Row(Build(quotas: [stale]), "monitoring").State == "stale", "last-known quota stays stale");
Check(Row(Build(quotas: [freshQuota with { FreshUntil = now.AddMinutes(-1) }]), "monitoring").State == "stale", "explicit quota expiry respected even with old ok status");
var mixed = Row(Build(quotas: [freshQuota, stale]), "monitoring");
Check(mixed.State == "partial" && mixed.Value.Contains("1 last known"), "mixed window freshness preserved");
var unsupported = freshQuota with { State = "unsupported", Used = null, Limit = null, Remaining = null };
var unsupportedSummary = Build(configured, quotas: [unsupported]);
Check(Row(unsupportedSummary, "monitoring").State == "unsupported", "unsupported monitoring neutral and scoped");
Check(Row(unsupportedSummary, "inference").State == "configured", "monitoring unsupported does not disable inference declaration");
Check(Row(Build(quotas: [freshQuota with { AccountId = "other" }]), "monitoring").State == "not_observed", "other account readings ignored");
Check(Row(Build(quotas: [freshQuota with { LastSuccessAt = null, ObservedAt = null }]), "monitoring").State == "unknown", "no invented observation time");
Check(Row(Build(quotas: [freshQuota with { LastSuccessAt = now.AddDays(1) }]), "monitoring").State == "unknown", "future success timestamp cannot establish freshness");
Check(Row(Build(quotas: [freshQuota with { Used = double.NaN, Limit = double.PositiveInfinity, Remaining = null }]), "monitoring").State == "not_observed", "non-finite values not observations");
var monitorMode = Build(configured with { Enabled = false }, [Route("r1")], [freshQuota], ready with { RuntimeMode = "monitor" });
Check(Row(monitorMode, "gateway").State == "monitor_only", "monitor-only runtime explicit");
Check(Row(monitorMode, "model_routes").Detail.Contains("disabled"), "disabled account intent explicit without destroying saved routes");
Check(Row(monitorMode, "monitoring").State == "fresh", "account enablement does not erase observation evidence");
var missing = Build(account with { State = "missing-credential", Capabilities = [new("inference", "missing-credential")] });
Check(Row(missing, "credential").State == "missing" && Row(missing, "inference").State == "missing", "local missing credential distinguished");
Check(Row(Build(account with { ExpiresAt = now }), "credential").State == "expired", "credential expiry remains local evidence");
Check(Row(Build(configured with { ExpiresAt = now }), "inference").State == "expired", "legacy shared credential expiry applies to declared purpose");
var binding = new ResourceBindingDto("synthetic");
var handle = new CredentialHandleDto("credential-1", 1, "static-key", ["inference"], binding, now.AddDays(1));
var explicitPurpose = Build(account with { Credentials = [handle] });
Check(Row(explicitPurpose, "inference").State == "configured" && Row(explicitPurpose, "inference").Evidence == "credential_purpose", "explicit handle purpose useful without legacy guessing");
var expiredHandle = Build(account with { Credentials = [handle with { ExpiresAt = now.AddDays(-1) }] });
Check(Row(expiredHandle, "inference").State == "expired", "purpose credential expiry scoped");
var uncertainHandle = Build(account with { Credentials = [handle with { ExpiresAt = now.AddDays(-1) }, handle with { Id = "credential-2", ExpiresAt = null }] });
Check(Row(uncertainHandle, "inference").State == "configured", "unknown expiry does not become inferred expiry");
Check(Row(Build(account with { Capabilities = [] }), "inference").State == "not_configured", "explicitly empty capabilities differ from legacy null");
Check(Build(routes: [Route("r1"), Route("r1")]).ConfiguredRouteCount == 1, "duplicate route identities not double counted");
var secretErrors = Build(configured with { Capabilities = [new("quota", "error", Error: "SYNTHETIC_SECRET_CANARY")] }, quotas: [unsupported with { Error = "SYNTHETIC_SECRET_CANARY" }], status: ready with { Error = "SYNTHETIC_SECRET_CANARY" });
Check(!JsonSerializer.Serialize(secretErrors).Contains("SYNTHETIC_SECRET_CANARY"), "raw provider errors not echoed");
Console.WriteLine($"Account outcome summary: {assertions} assertions passed; pure snapshots, no provider calls.");
RouteDto Route(string id, bool enabled = true, bool visible = true) => new(id, "alias", "model", "synthetic", [account.Id], Enabled: enabled, Visible: visible);
void Check(bool value, string message) { assertions++; if (!value) throw new Exception(message); }
